// <auto-generated>
// Campground.Shared — compiled into each Campground plugin as internal code.
// Edit it in AHouseOfBards/Campground-Coordination/shared, never inside a plugin.
// </auto-generated>
#nullable enable

using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Linq;
using System.Text.Json;
using System.Threading;
using System.Threading.Tasks;

namespace Campground.Shared.Registry
{
    /// <summary>Capability names. A name ends in its major version; a breaking change is a new name.</summary>
    internal static class CapabilityNames
    {
        internal const string Household = "campground.household.v1";
        internal const string Device = "campground.device.v1";
        internal const string Sessions = "campground.sessions.v1";
        internal const string Ports = "campground.ports.v1";
        internal const string Https = "campground.https.v1";
        internal const string Accounts = "campground.accounts.v1";
    }

    /// <summary>
    /// One operation handler: (operation, arguments) → result. BCL types only, so it crosses load contexts.
    /// </summary>
    internal static class Capabilities
    {
        private const string SectionName = "capabilities";

        /// <summary>Default time a caller waits for another plugin before carrying on alone.</summary>
        internal static readonly TimeSpan DefaultTimeout = TimeSpan.FromSeconds(2);

        /// <summary>
        /// Offers a capability. <paramref name="minor"/> rises with every backwards-compatible addition.
        /// Several plugins may offer the same name; callers get the highest minor.
        /// </summary>
        internal static void Provide(
            string name,
            string pluginId,
            int minor,
            Func<string, JsonElement, CancellationToken, Task<JsonElement>> handler)
        {
            var providers = ProvidersOf(name);
            providers[pluginId] = new Dictionary<string, object?>(StringComparer.Ordinal)
            {
                ["name"] = name,
                ["pluginId"] = pluginId,
                ["minor"] = minor,
                ["invoke"] = handler,
                ["registeredUtc"] = DateTime.UtcNow,
            };
        }

        /// <summary>Withdraws a capability this plugin offered.</summary>
        internal static void Withdraw(string name, string pluginId) => ProvidersOf(name).TryRemove(pluginId, out _);

        /// <summary>Whether anyone offers <paramref name="name"/> at <paramref name="minMinor"/> or later.</summary>
        internal static bool IsAvailable(string name, int minMinor = 0) => Resolve(name, minMinor) != null;

        /// <summary>Who provides it (plugin id), or null.</summary>
        internal static string? ProviderOf(string name, int minMinor = 0)
        {
            var record = Resolve(name, minMinor);
            return record == null ? null : CampgroundRegistry.Get<string>(record, "pluginId");
        }

        /// <summary>
        /// Calls an operation. Fails open: null when nobody provides it, the version is too old, it throws,
        /// or it takes longer than <paramref name="timeout"/>.
        /// </summary>
        internal static async Task<JsonElement?> TryInvokeAsync(
            string name,
            string operation,
            object? args,
            int minMinor = 0,
            TimeSpan? timeout = null,
            CancellationToken ct = default)
        {
            var record = Resolve(name, minMinor);
            if (record == null)
            {
                return null;
            }

            var invoke = CampgroundRegistry.Get<Func<string, JsonElement, CancellationToken, Task<JsonElement>>>(record, "invoke");
            if (invoke == null)
            {
                return null;
            }

            var payload = args is null ? CampgroundRegistry.EmptyObject
                : args is JsonElement e ? e
                : CampgroundRegistry.ToJson(args);

            var result = await CampgroundRegistry.WithTimeout<JsonElement?>(
                async token => await invoke(operation, payload, token).ConfigureAwait(false),
                timeout ?? DefaultTimeout,
                ct).ConfigureAwait(false);
            return result;
        }

        /// <summary>Typed form of <see cref="TryInvokeAsync"/>.</summary>
        internal static async Task<T?> TryInvokeAsync<T>(
            string name,
            string operation,
            object? args,
            int minMinor = 0,
            TimeSpan? timeout = null,
            CancellationToken ct = default)
        {
            var result = await TryInvokeAsync(name, operation, args, minMinor, timeout, ct).ConfigureAwait(false);
            return result.HasValue ? CampgroundRegistry.FromJson<T>(result.Value) : default;
        }

        /// <summary>All names currently offered, with their providers (for the "Campground on this server" panel).</summary>
        internal static IReadOnlyList<(string Name, string PluginId, int Minor)> List()
        {
            var list = new List<(string, string, int)>();
            foreach (var pair in CampgroundRegistry.Section(SectionName))
            {
                if (pair.Value is not ConcurrentDictionary<string, object> providers)
                {
                    continue;
                }

                foreach (var p in providers.Values.OfType<IReadOnlyDictionary<string, object?>>())
                {
                    list.Add((pair.Key, CampgroundRegistry.Get<string>(p, "pluginId") ?? "?", CampgroundRegistry.Get<int>(p, "minor")));
                }
            }

            return list.OrderBy(x => x.Item1, StringComparer.Ordinal).ToList();
        }

        private static ConcurrentDictionary<string, object> ProvidersOf(string name)
        {
            var section = CampgroundRegistry.Section(SectionName);
            var value = section.GetOrAdd(name, _ => new ConcurrentDictionary<string, object>(StringComparer.Ordinal));
            return value as ConcurrentDictionary<string, object> ?? new ConcurrentDictionary<string, object>();
        }

        private static IReadOnlyDictionary<string, object?>? Resolve(string name, int minMinor)
        {
            IReadOnlyDictionary<string, object?>? best = null;
            var bestMinor = int.MinValue;
            foreach (var p in ProvidersOf(name).Values.OfType<IReadOnlyDictionary<string, object?>>())
            {
                var minor = CampgroundRegistry.Get<int>(p, "minor");
                if (minor >= minMinor && minor > bestMinor)
                {
                    best = p;
                    bestMinor = minor;
                }
            }

            return best;
        }
    }

    /// <summary>
    /// Builds a capability handler from named operations, so providers write ordinary typed methods.
    /// </summary>
    internal sealed class CapabilityHost
    {
        private readonly Dictionary<string, Func<JsonElement, CancellationToken, Task<JsonElement>>> _ops = new(StringComparer.Ordinal);

        /// <summary>Adds an operation taking <typeparamref name="TArgs"/> and returning <typeparamref name="TResult"/>.</summary>
        internal CapabilityHost On<TArgs, TResult>(string operation, Func<TArgs, CancellationToken, Task<TResult>> handler)
        {
            _ops[operation] = async (json, ct) =>
            {
                var args = CampgroundRegistry.FromJson<TArgs>(json);
                if (args is null)
                {
                    throw new ArgumentException($"Arguments for '{operation}' could not be read.");
                }

                var result = await handler(args, ct).ConfigureAwait(false);
                return CampgroundRegistry.ToJson(result);
            };
            return this;
        }

        /// <summary>The handler to pass to <see cref="Capabilities.Provide"/>. Unknown operations throw (the caller fails open).</summary>
        internal Func<string, JsonElement, CancellationToken, Task<JsonElement>> Build()
            => (operation, args, ct) => _ops.TryGetValue(operation, out var op)
                ? op(args, ct)
                : throw new NotSupportedException($"Unknown operation '{operation}'.");
    }
}
